<?php
declare(strict_types=1);
function nota_campos(array $m=[],bool $foto=true): void {
    $grado=(string)($m['grado']??'10');$premios=[];foreach(q('SELECT nota,monto FROM '.t('premios').' ORDER BY nota')as$r)$premios[(int)$r['nota']]=(int)$r['nota']<7?0:(int)$r['monto'];
    ?><div class="nota-campos" data-premios="<?=h(json_encode($premios))?>"><label>Nota<select name="grado" required data-nota-grado><?php for($g=10;$g>=0;$g--)opciones([$g=>$g===10?'10 / Excelente':(string)$g],$grado); ?></select></label><?php campo('materia','Materia','text',(string)($m['materia']??''),true,'maxlength="80"');campo('fecha_nota','Fecha de la nota','date',(string)($m['fecha_nota']??nota_hoy()),true,'max="'.h(nota_hoy()).'"'); ?><label>Tipo de nota<select name="tipo_nota" required><?php opciones(array_combine(TIPOS_NOTA,TIPOS_NOTA),(string)($m['tipo_nota']??'Prueba')); ?></select></label><p class="nota-premio" aria-live="polite">Premio según la nota: <strong data-nota-importe><?=h(dinero($premios[(int)$grado]??0))?></strong></p><p class="sutil">El sitio calcula el importe al guardar. Menos de 7 se registra sin premio.</p><noscript><p>Podés enviar igual: el servidor calcula el premio con la nota elegida.</p></noscript><?php if($foto): campo('nota','Comentario (opcional)','text',(string)($m['nota']??''),false,'maxlength="230"'); ?><label class="subir-nota">Subir foto de la nota (opcional)<input type="file" name="foto_nota" accept="image/*"></label><p class="sutil">Foto JPG, PNG o WebP, hasta 10 MB y 16 megapíxeles. Podés elegir cámara o galería si tu celular lo ofrece. La foto sólo la ven vos y los adultos.</p><?php endif; ?></div><?php
}
function nota_foto_url(int $id): string {return ruta('/nota-foto.php').'?'.http_build_query(['id'=>$id,'token'=>hash_hmac('sha256','nota-foto:'.$id,csrf())]);}
function nota_detalle_vista(array $m): void {
    if($m['grado']===null||$m['tipo']!=='ingreso'||$m['inverso_de']!==null)return;
    ?><div class="nota-detalle"><p class="sutil">Nota <?=h($m['grado'])?> · <?=h($m['materia'])?> · <?=h($m['tipo_nota']??'Tipo anterior sin registrar')?> · <?=h($m['fecha_nota']??'Fecha anterior sin registrar')?></p><?php
    if($m['foto_nota']):$url=nota_foto_url((int)$m['foto_nota']); ?><a class="nota-foto-enlace" data-foto href="<?=h($url)?>" target="_blank" rel="noopener noreferrer"><img class="nota-miniatura" loading="lazy" src="<?=h($url)?>" alt="Foto de la nota de <?=h($m['materia'])?>"><span>Ampliar foto de la nota</span></a><?php endif;
    foreach(q('SELECT e.*,u.nombre FROM '.t('notas_eventos').' e JOIN '.t('usuarios').' u ON u.id=e.actor WHERE e.movimiento=? OR e.nuevo=? ORDER BY e.id',[$m['id'],$m['id']])as$e){if($e['tipo']!=='correccion'){?><p class="sutil nota-evento"><?=h($e['motivo'])?> · <?=h($e['nombre'])?> · <?=h(fecha($e['fecha']))?></p><?php continue;}$antes=json_decode($e['anterior'],true);$despues=json_decode($e['actual'],true); ?><p class="aviso nota-evento">Corregida de <?=h($antes['grado'])?> a <?=h($despues['grado'])?> por <?=h($e['nombre'])?>, el <?=h(fecha($e['fecha']))?>. <?=h($e['motivo'])?><?php if($e['nuevo']): ?> · Original #<?=h($e['movimiento'])?>, reemplazo #<?=h($e['nuevo'])?>.<?php endif; ?></p><?php }
    if($m['correccion_de']): ?><p>Reemplaza la nota del movimiento #<?=h($m['correccion_de'])?>.</p><?php endif; ?></div><?php
}
function nota_corregir_vista(array $m): void {
    if($m['grado']===null||$m['tipo']!=='ingreso'||$m['inverso_de']!==null||!in_array($m['estado'],['pendiente','confirmado'],true))return;
    ?><details class="corregir-nota"><summary>Corregir nota</summary><?php formulario('nota_corregir',['id'=>$m['id'],'version'=>nota_version($m),'volver'=>$m['estado']==='pendiente'?'':'historial']);nota_campos($m,false);campo('motivo','Motivo de la corrección','text','',true,'maxlength="230"'); ?><p class="sutil"><?=$m['estado']==='pendiente'?'Se guarda la corrección; después podés aprobarla.':'Se anula el original y se crea la nota corregida ya confirmada. Si no hay saldo suficiente, no se cambia nada.'?></p><button>Guardar corrección</button></form></details><?php
}
function retiro_vista(): void {
    if(!motivos_retiro()){?><section class="tarjeta" id="sacar-plata"><h2>Sacar plata de mi Cuenta Ahorro</h2><p>No hay motivos de retiro habilitados. Pedile a un adulto que los active en Configuración.</p></section><?php return;}
    ?><section class="tarjeta" id="sacar-plata"><h2>Sacar plata de mi Cuenta Ahorro</h2><p>Se reserva hasta que un adulto entregue la plata.</p><p class="sutil">Si ya gastaste efectivo que tenías en la mano, anotalo en Efectivo.</p><?php formulario('rescate');campo('monto','¿Cuántos pesos querés sacar?','number','',true,'min="1" max="10000000" step="1" inputmode="numeric"'); ?><label>¿Para qué?<select name="motivo" required><?php opciones(motivos_retiro()); ?></select></label><?php campo('nota','Algo más (opcional)','text','',false,'maxlength="300"'); ?><button>Pedir sacar plata</button></form></section><?php
}
function pendientes_vista_c8(): void {
    $pag=entero(get_texto('pend_pagina',6)?:'1',1,999999);$offset=($pag-1)*50;
    $lista=q("SELECT 'movimiento' clase,m.id,m.fecha FROM ".t('movimientos')." m JOIN ".t('usuarios')." u ON u.id=m.usuario WHERE m.estado='pendiente' AND m.creado_por=m.usuario AND u.rol='nino' AND u.activo=1 UNION ALL SELECT 'rescate' clase,r.id,r.fecha FROM ".t('rescates')." r JOIN ".t('usuarios')." u ON u.id=r.usuario WHERE r.estado IN ('pendiente','aprobado') AND u.activo=1 ORDER BY fecha,clase,id LIMIT 51 OFFSET ".$offset)->fetchAll();
    ?><section class="tarjeta" id="pendientes"><h2>Pendientes</h2><p class="sutil">Ingresos y notas por aprobar, retiros para entregar. Primero los más antiguos.</p><?php if(!$lista): ?><p>Todo al día. No hay pendientes.</p><?php endif;
    foreach(array_slice($lista,0,50)as$item){
        if($item['clase']==='rescate'){$r=uno('SELECT r.*,u.nombre,d.nombre decisor,e.nombre entrega,a.nombre aprobador FROM '.t('rescates').' r JOIN '.t('usuarios').' u ON u.id=r.usuario LEFT JOIN '.t('usuarios').' d ON d.id=r.decidido_por LEFT JOIN '.t('usuarios').' e ON e.id=r.entregado_por LEFT JOIN '.t('usuarios').' a ON a.id=r.aprobado_por WHERE r.id=?',[$item['id']]);rescate_articulo($r,true);continue;}
        $m=uno('SELECT m.*,u.nombre FROM '.t('movimientos').' m JOIN '.t('usuarios').' u ON u.id=m.usuario WHERE m.id=?',[$item['id']]);
        ?><article class="movimiento" id="pendiente-<?=h($m['id'])?>"><p class="ceja"><?=$m['tipo']==='egreso'?'Gasto anterior por resolver':($m['grado']!==null?'Nota del colegio · Para aprobar':'Ingreso por aprobar')?></p><div class="fila entre"><h3><?=h($m['nombre'].' · '.$m['concepto'])?></h3><strong><?=h(dinero((int)$m['monto']))?></strong></div><p class="sutil"><?=h(fecha($m['fecha']))?></p><?php if($m['nota']!==''): ?><p><?=h($m['nota'])?></p><?php endif;nota_detalle_vista($m);nota_corregir_vista($m); ?><div class="fila"><?php formulario('aprobar_movimiento',['id'=>$m['id']]); ?><button><?=$m['tipo']==='egreso'?'Confirmar gasto anterior':'Aprobar'?></button></form><?php formulario('rechazar_movimiento',['id'=>$m['id']]); ?><button class="secundario">Rechazar</button></form></div></article><?php
    }
    ?><nav class="paginacion" aria-label="Páginas de pendientes"><?php if($pag>1): ?><a href="<?=h(ruta('/?pend_pagina='.($pag-1)))?>#pendientes">Anteriores</a><?php endif;if(count($lista)>50): ?><a href="<?=h(ruta('/?pend_pagina='.($pag+1)))?>#pendientes">Más pendientes</a><?php endif; ?></nav></section><?php
}
